"""Randomised differential test: submission vs. naive reference."""
import json, random, subprocess, sys, os

sys.path.insert(0, '/workspace')
import ref as refmod

KINDS = ['fifo', 'sp', 'sff', 'wfq']


def gen_run(rng, nid, big=False):
    M = rng.randint(1, 4) if not big else rng.randint(1, 6)
    L = rng.randint(1, 3)
    # tiny byte limits exercise rejection and pushout
    if big:
        fifo_bytes = rng.choice([rng.randint(1, 40), rng.randint(1, 3000)])
        pifo_bytes = rng.choice([rng.randint(1, 40), rng.randint(1, 3000)])
    else:
        fifo_bytes = rng.choice([rng.randint(1, 12), rng.randint(1, 60)])
        pifo_bytes = rng.choice([rng.randint(1, 12), rng.randint(1, 60)])
    refill = rng.randint(1, 4)
    period = rng.choice([1, 2, 3, 5, 100000])
    U = rng.choice([5, 9, 20, 50, 100])
    # random strictly increasing borders from 0 to U
    nr = rng.randint(1, min(6, U))
    cuts = sorted(rng.sample(range(1, U), nr - 1)) if nr > 1 else []
    borders = [0] + cuts + [U]
    policy = {}
    kind = rng.choice(KINDS)
    policy['kind'] = kind
    flows = rng.sample(range(0, 8), rng.randint(1, 4))
    if kind == 'sp':
        policy['levels'] = [[f, rng.randint(0, 12)] for f in flows]
    elif kind == 'wfq':
        policy['weights'] = [[f, rng.randint(1, 6)] for f in flows]
    events = []
    ids = iter(range(nid, nid + 100000))
    used_ids = []
    saved = []
    nev = rng.randint(0, 40) if not big else rng.randint(0, 120)
    for _ in range(nev):
        choice = rng.random()
        if choice < 0.42:
            pid = next(ids)
            used_ids.append(pid)
            length = rng.choice([1, 1, 2, 3, 5, 8, 13])
            flow = rng.choice(flows)
            fsize = rng.choice([0, 1, 2, 3, 7, 11, 19])
            events.append(["enqueue", pid, flow, length, fsize])
        elif choice < 0.68:
            events.append(["dequeue", rng.randint(1, 6)])
        elif choice < 0.74:
            events.append(["sample"])
        elif choice < 0.80:
            # repartition with the same endpoints
            k = rng.randint(1, min(6, U))
            cuts = sorted(rng.sample(range(1, U), k - 1)) if k > 1 else []
            events.append(["repartition", [0] + cuts + [U]])
        elif choice < 0.87:
            target = rng.choice(used_ids) if used_ids and rng.random() < 0.75 else rng.randint(0, 500)
            events.append(["cancel", target])
        elif choice < 0.93:
            target = rng.choice(used_ids) if used_ids and rng.random() < 0.75 else rng.randint(0, 500)
            events.append(["inspect", target])
        elif choice < 0.96 and kind == 'wfq':
            events.append(["weight", rng.choice(flows), rng.randint(1, 8)])
        elif choice < 0.98:
            name = rng.randint(0, 5)
            events.append(["save", name])
            if name in saved:
                saved.remove(name)
            saved.append(name)
        else:
            if saved:
                events.append(["restore", rng.choice(saved)])
            else:
                events.append(["sample"])
    return {"banks": M, "load_balancers": L, "fifo_bytes": fifo_bytes,
            "pifo_bytes": pifo_bytes, "refill_batch": refill,
            "sample_period": period, "borders": borders, "policy": policy,
            "events": events}


def gen_request(rng, nruns=None, big=False):
    n = nruns if nruns else rng.randint(0, 4)
    nid = 0
    runs = []
    for _ in range(n):
        r = gen_run(rng, nid, big)
        nid += 100000
        runs.append(r)
    return {"runs": runs}


def run_cli(path, data):
    p = subprocess.run([sys.executable, '-I', '-B', path], input=data,
                       capture_output=True, cwd='/workspace')
    if p.returncode != 0:
        raise RuntimeError('nonzero exit: %r' % p.stderr[-2000:])
    return p.stdout.decode('utf-8')


def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 0
    count = int(sys.argv[2]) if len(sys.argv) > 2 else 300
    big = len(sys.argv) > 3 and sys.argv[3] == 'big'
    entry = '/workspace/submission/cli.py'
    bad = 0
    for trial in range(count):
        rng = random.Random(seed * 100003 + trial)
        req = gen_request(rng, big=big)
        data = json.dumps(req).encode()
        got = json.loads(run_cli(entry, data))
        exp = refmod.run_request(req)
        if got != exp:
            bad += 1
            print('MISMATCH trial', trial)
            open('/tmp/mismatch.json', 'w').write(json.dumps(req))
            for ri, (a, b) in enumerate(zip(got['runs'], exp['runs'])):
                if a != b:
                    print(' run', ri)
                    if a['log'] != b['log']:
                        for j, (x, y) in enumerate(zip(a['log'], b['log'])):
                            if x != y:
                                print('  log row', j, 'got', x, 'exp', y)
                                break
                        else:
                            print('  log lengths', len(a['log']), len(b['log']))
                    if a['state'] != b['state']:
                        for k in b['state']:
                            if a['state'].get(k) != b['state'][k]:
                                print('  state', k, 'got', a['state'].get(k), 'exp', b['state'][k])
                    break
            if bad >= 3:
                break
    print('done: %d/%d mismatches' % (bad, count))
    return 1 if bad else 0


if __name__ == '__main__':
    sys.exit(main())
